// Rebuilds stockfish-bundle.js, which lets the Screen Coach run when index.html is opened as a file.
// Usage: node vendor/stockfish/make-bundle.js
const fs = require('fs');
const path = require('path');
const dir = __dirname;
const js = fs.readFileSync(path.join(dir, 'stockfish-18-lite-single.js'), 'utf8');
const wasm = fs.readFileSync(path.join(dir, 'stockfish-18-lite-single.wasm')).toString('base64');
fs.writeFileSync(path.join(dir, 'stockfish-bundle.js'),
  '/* Stockfish.js 18 lite (GPLv3, see COPYING.txt) packed into one script: the engine source and its .wasm as base64.\n' +
  '   Generated by make-bundle.js; used when the app is opened as a file. */\n' +
  'window.STOCKFISH_BUNDLE = { js: ' + JSON.stringify(js) + ',\nwasm: "' + wasm + '" };\n');
